<script setup>
import {ref,onMounted,watch} from 'vue';
import {api,time} from './api';
const contracts=ref([]),cases=ref([]),evaluations=ref([]),legacy=ref([]),error=ref(''),busy=ref(false),contractId=ref(''),results=ref([]),labelRun=ref(),labelReview=ref(''),sampleName=ref(''),split=ref('development'),risks=ref([]);
const scoreCase=ref(''),scoreReview=ref(''),scoreResults=ref([]),scoreFindings=ref([]),matches=ref([]),cost=ref(null);
async function load(){try{const [c,s,e]=await Promise.all([api('/contracts?page=1'),api('/agent/evaluation-cases'),api('/agent/evaluations')]);contracts.value=c.items;cases.value=s;evaluations.value=e;}catch(e){error.value=e.message;}}
watch(contractId,async id=>{labelReview.value='';labelRun.value=null;results.value=[];if(id)try{const c=await api('/contracts/'+id);results.value=c.reviews.filter(r=>r.engine==='harness-v1'&&r.status==='completed');}catch(e){error.value=e.message;}});
watch(labelReview,async id=>{risks.value=[];try{labelRun.value=id?await api('/reviews/'+id):null;}catch(e){error.value=e.message;}});
function addRisk(){risks.value.push({id:crypto.randomUUID(),title:'',severity:'high',anchor:'',quote:'',expectedAdvice:''});}
function anchors(){return (labelRun.value?.documents||[]).flatMap(d=>(d.version?.parsed?.blocks||[]).map(b=>({key:d.versionId+':'+b.id,versionId:d.versionId,blockId:b.id,text:b.text,label:d.filename+' · '+b.id+' · '+b.text.slice(0,70)})));}
function selectAnchor(r){r.quote=anchors().find(a=>a.key===r.anchor)?.text||'';}
async function saveLabel(){busy.value=true;try{await api('/agent/evaluation-cases',{method:'POST',body:{name:sampleName.value,reviewId:labelReview.value,split:split.value,risks:risks.value.map(r=>{const a=anchors().find(a=>a.key===r.anchor);return {id:r.id,title:r.title,severity:r.severity,expectedAdvice:r.expectedAdvice,evidence:a?[{versionId:a.versionId,blockId:a.blockId,quote:r.quote}]:[]};})}});await load();sampleName.value='';risks.value=[];error.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
watch(scoreCase,async id=>{scoreReview.value='';scoreResults.value=[];matches.value=[];const c=cases.value.find(c=>c.id===id);if(!c)return;try{const r=await api('/reviews/'+c.expected.sourceReviewId),contract=await api('/contracts/'+r.contract_id);scoreResults.value=contract.reviews.filter(r=>r.engine==='harness-v1'&&r.status==='completed');matches.value=c.expected.risks.map(r=>({riskId:r.id,title:r.title,findingId:'',evidenceCorrect:false,adviceAcceptable:false}));}catch(e){error.value=e.message;}});
watch(scoreReview,async id=>{scoreFindings.value=[];if(id)try{scoreFindings.value=(await api('/reviews/'+id)).findings.filter(f=>f.check_status==='fail');}catch(e){error.value=e.message;}});
async function saveScore(){busy.value=true;try{await api('/agent/evaluations',{method:'POST',body:{caseId:scoreCase.value,reviewId:scoreReview.value,matches:matches.value.filter(m=>m.findingId).map(({title,...m})=>m),cost:cost.value===''?null:cost.value,costCurrency:'CNY'}});await load();error.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
const percentage=v=>v==null?'无可计算样本':(v*100).toFixed(1)+'%';
async function history(){try{legacy.value=(await api('/evaluations')).filter(e=>e.config?.engine!=='harness-v1');}catch(e){error.value=e.message;}}
onMounted(load);
</script>
<template>
  <section class="page-heading"><div><h1>审查质量评测</h1><p>法务标注风险、证据和期望改稿，再核对 Agent 结果。读取覆盖不作为风险识别率。</p></div></section>
  <p v-if="error" role="alert" class="notice danger">{{error}}</p>
  <details class="panel evaluation-form"><summary>保存法务标注样本</summary><form class="stack" @submit.prevent="saveLabel">
    <label>样本名称<input v-model="sampleName" required maxlength="300" /></label>
    <label>合同<select aria-label="合同" v-model="contractId" required><option value="">选择合同</option><option v-for="c in contracts" :key="c.id" :value="c.id">{{c.title}}</option></select></label>
    <label>审查结果版本<select aria-label="审查结果版本" v-model="labelReview" required><option value="">选择已完成的结果</option><option v-for="r in results" :key="r.id" :value="r.id">{{time(r.created_at)}}</option></select></label>
    <label>样本集<select v-model="split"><option value="development">开发集</option><option value="holdout">独立验收集</option></select></label>
    <article v-for="(r,index) in risks" :key="r.id" class="evaluation-risk stack"><label>风险 {{index+1}}<input v-model="r.title" required maxlength="500" /></label><label>风险程度<select v-model="r.severity"><option value="high">高风险</option><option value="medium">中风险</option><option value="low">低风险</option></select></label><label>原文证据<select v-model="r.anchor" @change="selectAnchor(r)"><option value="">缺失条款或暂无原文</option><option v-for="a in anchors()" :key="a.key" :value="a.key">{{a.label}}</option></select></label><label v-if="r.anchor">逐字引用<textarea v-model="r.quote" rows="3" required /></label><label>期望修改意见<textarea v-model="r.expectedAdvice" rows="3" required maxlength="20000" /></label><button type="button" @click="risks.splice(index,1)">移除此条风险</button></article>
    <div class="action-row"><button type="button" :disabled="!labelRun" @click="addRisk">添加标注风险</button><button class="primary" :disabled="busy||!labelRun">保存标注</button></div>
  </form></details>
  <details class="panel evaluation-form"><summary>记录结果核对</summary><form class="stack" @submit.prevent="saveScore"><label>标注样本<select aria-label="标注样本" v-model="scoreCase" required><option value="">选择样本</option><option v-for="c in cases" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>待评测结果<select aria-label="待评测结果" v-model="scoreReview" required><option value="">选择同一材料的结果版本</option><option v-for="r in scoreResults" :key="r.id" :value="r.id">{{time(r.created_at)}}</option></select></label><article v-for="m in matches" :key="m.riskId" class="evaluation-risk stack"><b>{{m.title}}</b><label>匹配的 Agent 风险<select aria-label="匹配的 Agent 风险" v-model="m.findingId"><option value="">未识别此风险</option><option v-for="f in scoreFindings" :key="f.id" :value="f.id">{{f.title}}</option></select></label><label><input type="checkbox" v-model="m.evidenceCorrect" :disabled="!m.findingId" />引用证据准确</label><label><input type="checkbox" v-model="m.adviceAcceptable" :disabled="!m.findingId" />修改意见可接受</label></article><p class="muted">未匹配的 Agent 风险计为误报；请选择同一组固定材料，文件变更后需另建样本。</p><label>本轮网关账单费用（元，可选）<input type="number" min="0" step="0.0001" v-model.number="cost" /></label><button class="primary" :disabled="busy||!scoreReview">保存评测</button></form></details>
  <article class="panel evaluation-form" v-for="e in evaluations" :key="e.id"><h2>{{time(e.created_at)}}</h2><div class="filter-row"><p>高风险召回：{{percentage(e.result.metrics.highRiskRecall)}}</p><p>风险准确率：{{percentage(e.result.metrics.precision)}}</p><p>证据准确率：{{percentage(e.result.metrics.evidenceAccuracy)}}</p><p>改稿接受率：{{percentage(e.result.metrics.adviceAcceptance)}}</p></div><p>漏检 {{e.result.metrics.missedRisks.length}} 条 · 误报 {{e.result.metrics.falsePositives.length}} 条 · 模型请求 {{e.result.requests}} 次 · 耗时 {{e.result.elapsedMs==null?'未知':Math.round(e.result.elapsedMs/1000)+' 秒'}} · 人工操作 {{e.result.humanOperations}} 次 · 费用 {{e.result.cost==null?'未提供账单':e.result.cost+' 元'}}</p><p v-if="e.result.mockOnly" class="notice">工程模拟结果，只验证流程，不能作为法律质量验收。</p><p class="muted">{{e.result.metrics.acceptance}}</p></article>
  <details class="panel evaluation-form" @toggle="$event.target.open&&history()"><summary>历史评测记录</summary><p v-for="e in legacy" :key="e.id">{{time(e.created_at)}} · {{e.status}}</p></details>
</template>
<style scoped>.evaluation-form{padding:24px;margin:16px 0}.evaluation-form summary{cursor:pointer;margin-bottom:16px}.evaluation-risk{padding:18px;border:1px solid #dce4df;border-radius:10px}.evaluation-form select{max-width:100%}</style>
